    /*
     * Assign a Tenant
     * 
     * @param	parentId	UUID
     * @param	assignment 	Tenant 
     * @return	MessagingEndpoint
     */
    public MessagingEndpoint assignTenant( UUID parentId, Tenant assignment ) {
	    LOGGER.info("assigning Tenant as " + assignment.toString() );

	    MessagingEndpoint parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Tenant.class, assignment.getTenantId());

	    // ------------------------------------------
		// assign the Tenant to the parent entity
		// ------------------------------------------ 
	    parentEntity.setTenant( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Tenant
	 * 
	 * @param	parentId		UUID
	 * @return	MessagingEndpoint
	 */
	public MessagingEndpoint unAssignTenant( UUID parentId ) {
		MessagingEndpoint parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Tenant on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Tenant on the parent entithy
		// ------------------------------------------     
	    parentEntity.setTenant(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Streams
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	MessagingEndpoint
     */
    public MessagingEndpoint addToStreams( UUID parentId, TelemetryStream addTo ) {
	    LOGGER.info("handling AssignStreamsToMessagingEndpointEvent - " );
	    
	    MessagingEndpoint parentEntity = repository.findById(parentId).get();
	    TelemetryStream child = registry.project( TelemetryStream.class, addTo.getTelemetryStreamId());
	    
	    parentEntity.getStreams().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Streams
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	MessagingEndpoint
     */
	public MessagingEndpoint removeFromStreams( UUID parentId, TelemetryStream removeFrom ) {
	    LOGGER.info("handling RemoveStreamsFromMessagingEndpointEvent " );
	
	    MessagingEndpoint parentEntity = repository.findById(parentId).get();
	    TelemetryStream child = registry.project( TelemetryStream.class, removeFrom.getTelemetryStreamId());
	    
	    parentEntity.getStreams().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



